-- P_TYPE and P_CONTAINER pack several attributes into one string.
-- Splitting them makes each attribute filterable/groupable on its own.
--   P_TYPE      'STANDARD POLISHED TIN' -> class / finish / material
--   P_CONTAINER 'SM CASE'               -> size / type

-- Columns dropped from brz_part:
--   p_comment                    free-text filler generated by TPC-H, no analytical value
--   _batch_id, _source_relation  Bronze audit metadata: lineage questions are answered in Bronze;
--                                _loaded_at is kept (used by deduplicate and as freshness marker)

with source as (
    {{ deduplicate(ref('brz_part'), partition_by=['p_partkey']) }}
)

select
    -- keys
    p_partkey::varchar                                     as part_id,

    -- attributes
    trim(p_name)::varchar                                  as part_name,
    {{ clean_label('p_mfgr') }}::varchar                   as manufacturer,
    {{ clean_label('p_brand') }}::varchar                  as brand,
    {{ clean_label('p_type') }}::varchar                   as part_type,
    {{ clean_label("split_part(p_type, ' ', 1)") }}::varchar as part_class,
    {{ clean_label("split_part(p_type, ' ', 2)") }}::varchar as part_finish,
    {{ clean_label("split_part(p_type, ' ', 3)") }}::varchar as part_material,
    p_size::number(38, 0)                                  as part_size,
    trim(p_container)::varchar                             as container,
    case split_part(trim(p_container), ' ', 1)
        when 'SM' then 'Small'
        when 'MED' then 'Medium'
        when 'LG' then 'Large'
        when 'JUMBO' then 'Jumbo'
        when 'WRAP' then 'Wrap'
    end::varchar                                           as container_size,
    {{ clean_label("split_part(p_container, ' ', 2)") }}::varchar as container_type,

    -- measures
    p_retailprice::number(12, 2)                           as retail_price,

    _loaded_at
from source
